<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_role(['admin','faculty']);
$errors=[];$changed=false;$pdo=db();$userQuery=$pdo->prepare('SELECT username,password_hash FROM users WHERE user_id=:id');$userQuery->execute(['id'=>$_SESSION['user_id']]);$user=$userQuery->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){
	$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
	if(!password_verify($current,$user['password_hash']))$errors['current_password']='Current password is incorrect.';
	if(!valid_staff_password($new))$errors['new_password']='Use at least 8 characters, including a letter and a number.';
	if(password_verify($new,$user['password_hash']))$errors['new_password']='Choose a password different from your current password.';
	if($new!==$confirm)$errors['confirm_password']='Passwords do not match.';
	if(!verify_csrf(isset($_POST['csrf_token'])?(string)$_POST['csrf_token']:null))$errors['form']='Your session expired. Reload and try again.';
	if(!$errors){$update=$pdo->prepare('UPDATE users SET password_hash=:hash,must_change_password=0 WHERE user_id=:id');$update->execute(['hash'=>password_hash($new,PASSWORD_DEFAULT),'id'=>$_SESSION['user_id']]);log_activity($pdo,'password_change');session_regenerate_id(true);$_SESSION['csrf_token']=bin2hex(random_bytes(32));$changed=true;}
}
$pageTitle='Change Password';require __DIR__.'/../includes/header.php';
?>
<section class="admin-shell"><aside class="admin-sidebar"><a href="<?=BASE_URL?>/admin/dashboard.php">Overview</a><a href="<?=BASE_URL?>/admin/manage-notices.php">Manage notices</a><a href="<?=BASE_URL?>/admin/profile.php">My profile</a><a class="active" href="<?=BASE_URL?>/admin/change-password.php">Change password</a></aside><div class="admin-content"><div class="admin-heading"><div><p class="eyebrow">Account security</p><h1>Change password</h1></div></div><div class="admin-form profile-form account-card"><?php if($changed):?><div class="success-alert" role="status">Password changed successfully.</div><?php endif;?><?php if(!empty($errors['form'])):?><div class="form-alert" role="alert"><?=h($errors['form'])?></div><?php endif;?><form method="post" id="change-password-form"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div class="account-field"><label class="form-field" for="change-current-password">Current password</label><div class="password-input-wrap"><input id="change-current-password" type="password" name="current_password" required autocomplete="current-password"><button class="show-password" type="button" data-target="change-current-password" aria-pressed="false" aria-label="Show password">Show</button></div><small class="field-error"><?=h($errors['current_password']??'')?></small></div><div class="account-field"><label class="form-field" for="change-new-password">New password</label><div class="password-input-wrap"><input id="change-new-password" type="password" name="new_password" required autocomplete="new-password"><button class="show-password" type="button" data-target="change-new-password" aria-pressed="false" aria-label="Show password">Show</button></div><div class="strength-meter" aria-hidden="true"><span id="strength-bar"></span></div><small class="password-strength" id="password-strength" aria-live="polite">Password strength: weak</small><small class="field-error"><?=h($errors['new_password']??'')?></small></div><div class="account-field"><label class="form-field" for="change-confirm-password">Confirm new password</label><div class="password-input-wrap"><input id="change-confirm-password" type="password" name="confirm_password" required autocomplete="new-password"><button class="show-password" type="button" data-target="change-confirm-password" aria-pressed="false" aria-label="Show password">Show</button></div><small class="field-error"><?=h($errors['confirm_password']??'')?></small></div><button class="button button-primary" type="submit">Update password</button></form></div></div></section><script src="<?=BASE_URL?>/assets/js/admin.js?v=20261024-ui"></script>
<?php require __DIR__.'/../includes/footer.php'; ?>